#include "Align.hpp"
#include <cassert>
#include <iostream>

const string genomeSnippet = "";
const string testAgainst = "";

int main() {
    // same strings
    assert(needlemanWunsch("GATTACA", "GATTACA").score == 7);
    // one gap
    Alignment g = needlemanWunsch("GATTCA", "GATTACA");
    assert(g.score == 4 && g.a == "GATT-CA");
    // one mismatch
    assert(needlemanWunsch("GATTACA", "GATCACA").score == 5);
    // empty
    assert(needlemanWunsch("", "ACG").score == -6);

    cout << "all tests passed" << endl;

    // real data
    Alignment r = needlemanWunsch(genomeSnippet, testAgainst);
    cout << "score: " << r.score << "\n" << r.a << "\n" << r.b << endl;
}
